 d=json.loads((r/f'{n:02}-confirm-aggregate.json').read_text());ci=d['paired_bootstrap_95_ci'];lines.append(f"|{n:02}|{d['baseline_sum_median_ms']:.3f}|{d['candidate_sum_median_ms']:.3f}|{d['primary_speedup']:.4f}x|{ci[0]:.4f}–{ci[1]:.4f}|")
