with (r/'final-cases.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['case','threads','baseline_median_ms','baseline_p25_ms','baseline_p75_ms','final_median_ms','final_p25_ms','final_p75_ms','speedup'])
